def smallest_num(xs):
    """
    Return the smallest number in the iterable xs.
    If xs is empty, raises ValueError.
    """
    # Convert to iterator and get first element as initial minimum
    it = iter(xs)
    try:
        min_val = next(it)
    except StopIteration:
        raise ValueError("smallest_num() arg is an empty sequence")
    # Iterate through remaining items
    for v in it:
        if v < min_val:
            min_val = v
    return min_val

