def smallest_num(xs):
    """
    Return the smallest number in the iterable xs.
    If xs is empty, raises a ValueError.
    """
    if not xs:
        raise ValueError("empty sequence")
    # Initialize with the first element
    min_val = xs[0]
    for x in xs[1:]:
        if x < min_val:
            min_val = x
    return min_val

